INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7390836, 1161998, 65858, '<td valign="top">Wow, that''s cool!</td>', 'Wow, that''s cool!', '2015-07-22 01:03:52.000000', NULL, 1),
(7390839, 1162030, 65858, '<td valign="top">Awesome texture and color!</td>', 'Awesome texture and color!', '2015-07-22 01:04:27.000000', NULL, 1),
(7390865, 1161974, 96915, '<td valign="top">Fry-day?</td>', 'Fry-day?', '2015-07-22 01:17:34.000000', NULL, 1),
(7390892, 1162038, 180696, '<td valign="top">Nice curves</td>', 'Nice curves', '2015-07-22 01:45:01.000000', NULL, 1),
(7390898, 1162018, 180696, '<td valign="top">I know that the feature is supposed to be "Liquid", but I would have liked to see the entire apple, just a little cropped. The apple itself could have been more in focus and still show off the water pouring onto it and flowing around it.</td>', 'I know that the feature is supposed to be "Liquid", but I would have liked to see the entire apple, just a little cropped. The apple itself could have been more in focus and still show off the water pouring onto it and flowing around it.', '2015-07-22 01:48:03.000000', NULL, 1),
(7390911, 1162073, 43191, '<td valign="top">oh no looks like a corrupt file :(</td>', 'oh no looks like a corrupt file :(', '2015-07-22 02:01:38.000000', NULL, 1),
(7390912, 1162052, 180696, '<td valign="top">The main feature "Liquid" doesn''t seem to be standing out enough and feel that the bears are taking centre stage.</td>', 'The main feature "Liquid" doesn''t seem to be standing out enough and feel that the bears are taking centre stage.', '2015-07-22 02:02:26.000000', NULL, 1),
(7390916, 1161987, 180696, '<td valign="top">With the colour of the skies, the liquid seems to get lost amongst it. This challenge open for advanced editing, so I''m sure that you could have done something to improve on the colours or could have tried to take the image at a different time of the day, if possible. If it is a geyser erupting, I can understand that one cannot change or predict what and when they erupt.</td>', 'With the colour of the skies, the liquid seems to get lost amongst it. This challenge open for advanced editing, so I''m sure that you could have done something to improve on the colours or could have tried to take the image at a different time of the day, if possible. If it is a geyser erupting, I can understand that one cannot change or predict what and when they erupt.', '2015-07-22 02:07:32.000000', NULL, 1),
(7390918, 1162037, 180696, '<td valign="top">Great image, idea and clarity. I do find however that the rule of thirds could have improved this image a little more. It is very centred. Still a great capture with wonderful colours! :)</td>', 'Great image, idea and clarity. I do find however that the rule of thirds could have improved this image a little more. It is very centred. Still a great capture with wonderful colours! :)', '2015-07-22 02:09:11.000000', NULL, 1),
(7390922, 1161900, 33068, '<td valign="top">Without the title I wouldn''t  know this was for a liquid challenge. It is a nice image with excellent processing though.</td>', 'Without the title I wouldn''t  know this was for a liquid challenge. It is a nice image with excellent processing though.', '2015-07-22 02:11:24.000000', NULL, 1),
(7390923, 1161748, 180696, '<td valign="top">Pity that the glass is very tightly cropped at the bottom. I understand that you may have wanted to eliminate what the glass was standing on, but if you used the correct surface, you could have gotten away with having to crop it out this way. One has to very careful when using horizontal lines with another subject in the forefront, one can see that the glass is tilted slightly. Still a great image.</td>', 'Pity that the glass is very tightly cropped at the bottom. I understand that you may have wanted to eliminate what the glass was standing on, but if you used the correct surface, you could have gotten away with having to crop it out this way. One has to very careful when using horizontal lines with another subject in the forefront, one can see that the glass is tilted slightly. Still a great image.', '2015-07-22 02:12:58.000000', NULL, 1),
(7390925, 1161818, 180696, '<td valign="top">A great capture of the moment. This is a challenge with advanced editing allowed, but you could have tried this image with a little less harsh light, the colour of the stem of the glass is unfortunately lost and could have added value to the overall image.</td>', 'A great capture of the moment. This is a challenge with advanced editing allowed, but you could have tried this image with a little less harsh light, the colour of the stem of the glass is unfortunately lost and could have added value to the overall image.', '2015-07-22 02:15:55.000000', NULL, 1),
(7390929, 1161706, 50641, '<td valign="top">The leaves make me scared of the soup.</td>', 'The leaves make me scared of the soup.', '2015-07-22 02:22:03.000000', NULL, 1),
(7390940, 1162023, 65858, '<td valign="top">Ooh, lovely energy and color!</td>', 'Ooh, lovely energy and color!', '2015-07-22 02:40:36.000000', NULL, 1),
(7390942, 1161706, 180696, '<td valign="top">This could''ve been entered for the "Summertime meals" instead. I''m not convinced that , although you are trying to portray that soup is a winter type dish, that the leaves add any value to the image. Just my opinion</td>', 'This could''ve been entered for the "Summertime meals" instead. I''m not convinced that , although you are trying to portray that soup is a winter type dish, that the leaves add any value to the image. Just my opinion', '2015-07-22 02:41:58.000000', NULL, 1),
(7390947, 1161237, 180696, '<td valign="top">This challenge allows for advanced editing, but besides that, I feel that this seems more like a family holiday photo and sure whether the purists would resist the temptation to scrutinize this image in greater depth as to the creative worthiness of this image. The colours are very muted and could have been more bold and a better DOF could''ve got rid of the distracting background</td>', 'This challenge allows for advanced editing, but besides that, I feel that this seems more like a family holiday photo and sure whether the purists would resist the temptation to scrutinize this image in greater depth as to the creative worthiness of this image. The colours are very muted and could have been more bold and a better DOF could''ve got rid of the distracting background', '2015-07-22 02:46:41.000000', NULL, 1),
(7390948, 1161429, 180696, '<td valign="top">I love your idea, thinking out of the box! Cant find anything negative to comment on your entry!</td>', 'I love your idea, thinking out of the box! Cant find anything negative to comment on your entry!', '2015-07-22 02:48:43.000000', NULL, 1),
(7390949, 1162030, 180696, '<td valign="top">Unfortunately due to the angle of which the image was taken, the image seems a little flat. Yes, it is "liquid", but I find that something more creative could have been entered.</td>', 'Unfortunately due to the angle of which the image was taken, the image seems a little flat. Yes, it is "liquid", but I find that something more creative could have been entered.', '2015-07-22 02:50:43.000000', NULL, 1),
(7390950, 1162054, 180696, '<td valign="top">I understand what you attempted to create here, but I feel that the black and white may not have added the value it could have achieved. There may also be too much negative space on the left although I understand that you attempted to use the rule of thirds. I also have an issue with the black line just creeping in on the top of the image??</td>', 'I understand what you attempted to create here, but I feel that the black and white may not have added the value it could have achieved. There may also be too much negative space on the left although I understand that you attempted to use the rule of thirds. I also have an issue with the black line just creeping in on the top of the image??', '2015-07-22 02:54:26.000000', NULL, 1),
(7390951, 1162039, 180696, '<td valign="top">Nice depiction of the drinkable water as opposed to the non-drinkable water. The colours are good and nice sun flare.</td>', 'Nice depiction of the drinkable water as opposed to the non-drinkable water. The colours are good and nice sun flare.', '2015-07-22 02:55:43.000000', NULL, 1),
(7390952, 1162006, 180696, '<td valign="top">I like the fact that you used the rule of thirds here, it works well. Your image to me just seems to be over post-processed and this is noticeable in the flowers in the foreground. Just my opinion</td>', 'I like the fact that you used the rule of thirds here, it works well. Your image to me just seems to be over post-processed and this is noticeable in the flowers in the foreground. Just my opinion', '2015-07-22 02:57:39.000000', NULL, 1),
(7390953, 1161315, 180696, '<td valign="top">I always like silhouettes</td>', 'I always like silhouettes', '2015-07-22 02:59:03.000000', NULL, 1),
(7390954, 1162013, 180696, '<td valign="top">The theme is there for sure, but just struggle to find where the focus is, my eyes wonders all around looking for this...</td>', 'The theme is there for sure, but just struggle to find where the focus is, my eyes wonders all around looking for this...', '2015-07-22 03:00:18.000000', NULL, 1),
(7390956, 1160819, 180696, '<td valign="top">There is so much water that I feel you could''ve zoomed in a little more onto the duck and still get enough water to conform to the theme. The duck seems a little lost. The image could also have been taken at either of the "golden" hours of the day to add some colour like yellowish sunset colours or morning mist hanging over the water if possible. The image is a little too grey for me.</td>', 'There is so much water that I feel you could''ve zoomed in a little more onto the duck and still get enough water to conform to the theme. The duck seems a little lost. The image could also have been taken at either of the "golden" hours of the day to add some colour like yellowish sunset colours or morning mist hanging over the water if possible. The image is a little too grey for me.', '2015-07-22 03:04:21.000000', NULL, 1),
(7390957, 1161924, 180696, '<td valign="top">Focus is the largest issue here, amongst many others.</td>', 'Focus is the largest issue here, amongst many others.', '2015-07-22 03:05:14.000000', NULL, 1),
(7390958, 1161190, 180696, '<td valign="top">Focus on the water and glass would be great, but lacks that. I am also not sure whether the image works in black and white as it would''ve in colour. If the drink is beer, the colour could''ve added more creativity.</td>', 'Focus on the water and glass would be great, but lacks that. I am also not sure whether the image works in black and white as it would''ve in colour. If the drink is beer, the colour could''ve added more creativity.', '2015-07-22 03:08:41.000000', NULL, 1),
(7390959, 1161675, 180696, '<td valign="top">Focus on the droplets is good.</td>', 'Focus on the droplets is good.', '2015-07-22 03:09:07.000000', NULL, 1),
(7390960, 1161859, 180696, '<td valign="top">Nice focus on the cat. Like the colour of the image as a whole. :)</td>', 'Nice focus on the cat. Like the colour of the image as a whole. :)', '2015-07-22 03:10:10.000000', NULL, 1),
(7390963, 1161765, 180696, '<td valign="top">Difficult to determine where there is any area that has the best focus, if any.</td>', 'Difficult to determine where there is any area that has the best focus, if any.', '2015-07-22 03:12:46.000000', NULL, 1),
(7390965, 1162046, 180696, '<td valign="top">Good attempt as we all know that a lot of patience is required to get such an image right, this said, I find that you just missed out on slightly focus on the droplet itself.</td>', 'Good attempt as we all know that a lot of patience is required to get such an image right, this said, I find that you just missed out on slightly focus on the droplet itself.', '2015-07-22 03:16:34.000000', NULL, 1),
(7390972, 1162073, 180676, '<td valign="top">Not voiting...  think something glitched with this upload though?  Just pink/purple static, sorry.</td>', 'Not voiting...  think something glitched with this upload though?  Just pink/purple static, sorry.', '2015-07-22 03:36:14.000000', NULL, 1),
(7390973, 1161796, 180696, '<td valign="top">A colour in my opinion could have worked better here. A colour drop into the white liquid can be achieved if captured at the right time. I''ve seen it done with great achievement, but then again I accept that one tends not to create something that the masses do and think out of the box. The image is still well captured and we all know what patience it takes to attempt to get this image just right. :)</td>', 'A colour in my opinion could have worked better here. A colour drop into the white liquid can be achieved if captured at the right time. I''ve seen it done with great achievement, but then again I accept that one tends not to create something that the masses do and think out of the box. The image is still well captured and we all know what patience it takes to attempt to get this image just right. :)', '2015-07-22 03:39:13.000000', NULL, 1),
(7390974, 1161674, 180696, '<td valign="top">Better focusing on the water could''ve been great. I cant seem to find an area where the water is focused well enough. Slightly out of focus.</td>', 'Better focusing on the water could''ve been great. I cant seem to find an area where the water is focused well enough. Slightly out of focus.', '2015-07-22 03:43:00.000000', NULL, 1),
(7390976, 1162056, 180696, '<td valign="top">Don''t really get the sense of any water as the main future of the theme as liquid. The surface is in my opinion too busy and the droplets seem to be lost in the image. Good attempt though.</td>', 'Don''t really get the sense of any water as the main future of the theme as liquid. The surface is in my opinion too busy and the droplets seem to be lost in the image. Good attempt though.', '2015-07-22 03:50:55.000000', NULL, 1),
(7390978, 1161717, 180696, '<td valign="top">Nice attempt, but I feel that the whites are washed out. I think that this image could''ve been better depicted in colour. Only after peering very well at your photo, do I even realise the dog in the image, that''s why I feel a lot is lost in the possibly better depicted image. You had a wonderful idea here. :)</td>', 'Nice attempt, but I feel that the whites are washed out. I think that this image could''ve been better depicted in colour. Only after peering very well at your photo, do I even realise the dog in the image, that''s why I feel a lot is lost in the possibly better depicted image. You had a wonderful idea here. :)', '2015-07-22 03:54:57.000000', NULL, 1),
(7390982, 1161754, 180696, '<td valign="top">Fantastic image!! Well done!! :)</td>', 'Fantastic image!! Well done!! :)', '2015-07-22 04:01:58.000000', NULL, 1),
(7390983, 1161875, 180696, '<td valign="top">Very creative! Love it!</td>', 'Very creative! Love it!', '2015-07-22 04:03:10.000000', NULL, 1),
(7390984, 1161892, 180696, '<td valign="top">Great focus on the droplet, not very easilyachieved and takes a lot of trial and error, I know this as I do a lot of macro myself. Well done! :)</td>', 'Great focus on the droplet, not very easilyachieved and takes a lot of trial and error, I know this as I do a lot of macro myself. Well done! :)', '2015-07-22 04:04:40.000000', NULL, 1),
(7390988, 1161643, 180696, '<td valign="top">I find it slightly out of focus although you may have intended to achieve this. I feel that there should at least be some good focus on some of the area of the image. Otherwise a good photo with great colours.</td>', 'I find it slightly out of focus although you may have intended to achieve this. I feel that there should at least be some good focus on some of the area of the image. Otherwise a good photo with great colours.', '2015-07-22 04:07:36.000000', NULL, 1),
(7390989, 1161649, 180696, '<td valign="top">Sorry, but I feel that this image of yours is ore of a family album photo by comparison of most other images on this challenge. yes, it is "Liquid" as the theme is for this challenge, but not much creativity was used here</td>', 'Sorry, but I feel that this image of yours is ore of a family album photo by comparison of most other images on this challenge. yes, it is "Liquid" as the theme is for this challenge, but not much creativity was used here', '2015-07-22 04:10:15.000000', NULL, 1),
(7390990, 1161721, 180696, '<td valign="top">Lovely focusing on the pipette! Love the cropping and colour! :)</td>', 'Lovely focusing on the pipette! Love the cropping and colour! :)', '2015-07-22 04:12:20.000000', NULL, 1),
(7390991, 1161722, 180696, '<td valign="top">Fantastic image! :) Cant find too much wrong with it! :)</td>', 'Fantastic image! :) Cant find too much wrong with it! :)', '2015-07-22 04:13:04.000000', NULL, 1),
(7390993, 1161909, 180696, '<td valign="top">Nice attempt, but the image is clearly out of focus.</td>', 'Nice attempt, but the image is clearly out of focus.', '2015-07-22 04:13:38.000000', NULL, 1),
(7390995, 1161417, 180696, '<td valign="top">What can I say, This is a great portrayal of what can be achieved with such a shot! The clarity and sharpness is out of this world! I love all the milky colours and the fact that the splash is actually facing the viewer.</td>', 'What can I say, This is a great portrayal of what can be achieved with such a shot! The clarity and sharpness is out of this world! I love all the milky colours and the fact that the splash is actually facing the viewer.', '2015-07-22 04:15:36.000000', NULL, 1),
(7391003, 1161819, 180696, '<td valign="top">Good clarity</td>', 'Good clarity', '2015-07-22 04:42:35.000000', NULL, 1),
(7391004, 1161903, 180696, '<td valign="top">This image seems a little over saturated?? Nice ripple effect though :)</td>', 'This image seems a little over saturated?? Nice ripple effect though :)', '2015-07-22 04:44:03.000000', NULL, 1),
(7391005, 1161659, 180696, '<td valign="top">Great creativity! :)</td>', 'Great creativity! :)', '2015-07-22 04:44:19.000000', NULL, 1),
(7391006, 1161641, 180696, '<td valign="top">I know that a drop onto a drop is very difficult to achieve and one needs a lot of patience! I love macro shots and it is a passion of mine too. Great photo!</td>', 'I know that a drop onto a drop is very difficult to achieve and one needs a lot of patience! I love macro shots and it is a passion of mine too. Great photo!', '2015-07-22 04:46:45.000000', NULL, 1),
(7391008, 1161852, 180696, '<td valign="top">Lovely photo and colour hue. Just a pity about the little red spot in the background on the right of the image. This challenge allows advanced editing and thus I feel that the red/yellow spot could''ve been cloned out.</td>', 'Lovely photo and colour hue. Just a pity about the little red spot in the background on the right of the image. This challenge allows advanced editing and thus I feel that the red/yellow spot could''ve been cloned out.', '2015-07-22 04:48:40.000000', NULL, 1),
(7391009, 1161439, 180696, '<td valign="top">Nice depiction and DOF as well as composition, not to mention the fifties appeal of the image! :)</td>', 'Nice depiction and DOF as well as composition, not to mention the fifties appeal of the image! :)', '2015-07-22 04:49:38.000000', NULL, 1),
(7391010, 1161985, 180696, '<td valign="top">A little colour in the background as opposed to a pure black and white image could''ve added value to this nice shot. It could''ve brought out the water even more and it could possibly have created a little more creativity. Otherwise a good splash :)</td>', 'A little colour in the background as opposed to a pure black and white image could''ve added value to this nice shot. It could''ve brought out the water even more and it could possibly have created a little more creativity. Otherwise a good splash :)', '2015-07-22 04:52:33.000000', NULL, 1),
(7391011, 1161953, 180696, '<td valign="top">Nice use of the rule of thirds, clarity of the subject matter and good DOF :)</td>', 'Nice use of the rule of thirds, clarity of the subject matter and good DOF :)', '2015-07-22 04:53:39.000000', NULL, 1),
(7391012, 1161849, 180696, '<td valign="top">Nice photo&gt; I see that you didn''t attempt to create a black and white photo and I do see some colour in the background, and due to that and the fact that the image is lacking a little depth, you could''ve saturated the image a little to bring out the colours more. A little bit of contrast could also add some more value to your image. You have a good photo, but you could have edited it a little more. This challenge allows advanced editing.</td>', 'Nice photo> I see that you didn''t attempt to create a black and white photo and I do see some colour in the background, and due to that and the fact that the image is lacking a little depth, you could''ve saturated the image a little to bring out the colours more. A little bit of contrast could also add some more value to your image. You have a good photo, but you could have edited it a little more. This challenge allows advanced editing.', '2015-07-22 05:02:03.000000', NULL, 1),
(7391013, 1162069, 180696, '<td valign="top">Nice achievement and lovely colour</td>', 'Nice achievement and lovely colour', '2015-07-22 05:02:33.000000', NULL, 1),
(7391014, 1161652, 180696, '<td valign="top">Nice photo, may seem a little over-post processed, not sure?</td>', 'Nice photo, may seem a little over-post processed, not sure?', '2015-07-22 05:03:16.000000', NULL, 1),
(7391015, 1160720, 180696, '<td valign="top">Nice with the slightly slower shutter speed. Well balanced.</td>', 'Nice with the slightly slower shutter speed. Well balanced.', '2015-07-22 05:04:06.000000', NULL, 1),
(7391016, 1162048, 180696, '<td valign="top">Nice photo. I just feel that that the photo being in black and white, allows the water to appear a little lost.</td>', 'Nice photo. I just feel that that the photo being in black and white, allows the water to appear a little lost.', '2015-07-22 05:05:46.000000', NULL, 1),
