(7392178, 1161715, 96915, '<td valign="top">Beautiful.  I can feel the ocean on my toes.</td>', 'Beautiful.  I can feel the ocean on my toes.', '2015-07-26 00:46:30.000000', NULL, 1),
(7392180, 1161756, 96915, '<td valign="top">The DOF feels to shallow on this.  While the far edge is very sharp, there''s just too much in the foreground that isn''t.  I''m not a stickler for sharpness in most cases, but for droplets it makes a difference.</td>', 'The DOF feels to shallow on this.  While the far edge is very sharp, there''s just too much in the foreground that isn''t.  I''m not a stickler for sharpness in most cases, but for droplets it makes a difference.', '2015-07-26 00:48:59.000000', NULL, 1),
(7392181, 1160969, 96915, '<td valign="top">Beautiful clouds.  However, when I see clouds, I think gas rather than liquid.</td>', 'Beautiful clouds.  However, when I see clouds, I think gas rather than liquid.', '2015-07-26 00:49:43.000000', NULL, 1),
(7392183, 1162022, 96915, '<td valign="top">I wish I could be more specific here, but something about the lighting doesn''t work for me.  I do really like how the purple folds together towards the bottom of the frame though.</td>', 'I wish I could be more specific here, but something about the lighting doesn''t work for me.  I do really like how the purple folds together towards the bottom of the frame though.', '2015-07-26 00:51:52.000000', NULL, 1),
(7392185, 1161237, 96915, '<td valign="top">I love photographing kids in water.  The cropping of the top of her head feels awkward to me.</td>', 'I love photographing kids in water.  The cropping of the top of her head feels awkward to me.', '2015-07-26 00:54:09.000000', NULL, 1),
(7392188, 1162020, 96915, '<td valign="top">I love stormy coffee. I wish it had been more in focus rather than the back of the cup, and with less glare.</td>', 'I love stormy coffee. I wish it had been more in focus rather than the back of the cup, and with less glare.', '2015-07-26 00:56:15.000000', NULL, 1),
(7392239, 1161605, 180972, '<td valign="top">Great detail and dof!  Very nice work!</td>', 'Great detail and dof!  Very nice work!', '2015-07-26 15:26:38.000000', NULL, 1),
(7392240, 1161417, 180972, '<td valign="top">Very creative image!  It is beautiful and has great detail.</td>', 'Very creative image!  It is beautiful and has great detail.', '2015-07-26 15:30:54.000000', NULL, 1),
(7392248, 1161325, 180972, '<td valign="top">I love this image, but it is somewhat difficult to look at and I''m not sure what can be done to fix it.  Maybe a slightly shorter shutter speed would help.  This is a beautiful image though.</td>', 'I love this image, but it is somewhat difficult to look at and I''m not sure what can be done to fix it.  Maybe a slightly shorter shutter speed would help.  This is a beautiful image though.', '2015-07-26 15:39:39.000000', NULL, 1),
